<!DOCTYPE html><html><head>@include('admin.common.head')</head><body class="hold-transition sidebar-mini"><div class="wrapper">@include('admin.common.header')@include('admin.common.sidebar')<div class="content-wrapper"><section class="content"><h3>{{ $role->exists ? 'Edit' : 'Create' }} company role</h3><p class="text-muted">Permissions are action-based. Reserved permissions are classified by the canonical registry and are never available to Company Admins.</p><form method="POST" action="{{ $role->exists ? route('admin.roles.update', $role) : route('admin.roles.store') }}">@csrf @if($role->exists) @method('PUT') @endif<div class="row"><div class="col-sm-6"><label>Name</label><input class="form-control" name="name" value="{{ old('name', $role->name) }}" required></div><div class="col-sm-3"><label>Login panel</label><select class="form-control" name="panel" {{ $role->exists ? 'disabled' : '' }}><option value="Admin" @selected(old('panel', $role->panel ?: 'Admin') === 'Admin')>Admin</option><option value="Frontend" @selected(old('panel', $role->panel) === 'Frontend')>Frontend</option></select>@if($role->exists)<input type="hidden" name="panel" value="{{ $role->panel }}">@endif</div><div class="col-sm-3"><label>Status</label><select class="form-control" name="status"><option value="Active" @selected(old('status', $role->status ?: 'Active') === 'Active')>Active</option><option value="Inactive" @selected(old('status', $role->status) === 'Inactive')>Inactive</option></select></div></div><label>Description</label><textarea class="form-control" name="description">{{ old('description', $role->description) }}</textarea><hr><div class="form-inline"><input id="permission-filter" class="form-control" type="search" placeholder="Filter actions..."><button class="btn btn-default" type="button" id="select-visible">Select visible</button><button class="btn btn-default" type="button" id="clear-visible">Clear visible</button></div>@foreach($permissions as $resource => $items)<fieldset class="permission-module"><legend>{{ ucfirst(str_replace('-', ' ', $resource)) }} <small>({{ $items->count() }} actions)</small></legend><div class="row">@foreach($items as $permission)<div class="col-sm-4 permission-item" data-search="{{ strtolower($permission->permission_key.' '.$permission->description) }}"><label class="checkbox-inline"><input type="checkbox" name="permissions[]" value="{{ $permission->permission_key }}" @checked($role->permissions->contains('permission_key', $permission->permission_key))> {{ ucfirst(str_replace('-', ' ', $permission->action)) }} @if($permission->is_critical)<span class="label label-warning">critical</span>@endif</label></div>@endforeach</div></fieldset>@endforeach<button class="btn btn-primary" type="submit">Save role permissions</button></form></section></div></div>@include('admin.common.footer')<script>jQuery(function($){$('#permission-filter').on('input',function(){var q=this.value.toLowerCase();$('.permission-item').each(function(){$(this).toggle(!q||$(this).data('search').indexOf(q)!==-1);});});$('#select-visible').click(function(){$('.permission-item:visible input').prop('checked',true);});$('#clear-visible').click(function(){$('.permission-item:visible input').prop('checked',false);});});</script></body></html>
